    'models.get.lmsMac': '<strong>LM Studio\u00a0:</strong> dans <em>Discover</em>, recherchez <code>{name}</code> et privilégiez la version MLX.',
    'models.get.vllm': '<strong>vLLM</strong> (le plus rapide sur un Spark)\u00a0: servez {what} avec l\'appel d\'outils activé{flags}\u00a0; les <a href="{recipe}">vLLM Recipes</a> indiquent les options, et le <a href="https://build.nvidia.com/spark/vllm">playbook Spark</a> de NVIDIA le conteneur.',
